    private void btn_precioPromedioActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btn_precioPromedioActionPerformed
        ProductoDAO proDAO = new ProductoDAO();
        int mensaje = (int)proDAO.precioPromedio();
        JOptionPane.showMessageDialog(this, "El precio promedio de los productos es de: "+mensaje);
    }//GEN-LAST:event_btn_precioPromedioActionPerformed

